#include <iostream>
#include <vector>
#include <string>
#include <queue>
#include <functional>
#include <utility>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(3));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<pair<int, long long>>> adj(n + 1);
    for (const vector<long long>& e : edges) {
        adj[e[0]].push_back({(int)e[1], e[2]});
        adj[e[1]].push_back({(int)e[0], e[2]});
    }
    const long long INF = 1000000000000000000LL;
    vector<long long> d1(n + 1, INF), d2(n + 1, INF);
    d1[1] = 0;
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> heap;
    heap.push({0, 1});
    while (!heap.empty()) {
        pair<long long, int> top = heap.top();
        heap.pop();
        long long d = top.first;
        int u = top.second;
        if (d > d2[u]) continue;
        for (const auto& edge : adj[u]) {
            int v = edge.first;
            long long nd = d + edge.second;
            if (nd < d1[v]) {
                d2[v] = d1[v];
                d1[v] = nd;
                heap.push({nd, v});
                if (d2[v] < INF) heap.push({d2[v], v});
            } else if (d1[v] < nd && nd < d2[v]) {
                d2[v] = nd;
                heap.push({nd, v});
            }
        }
    }
    cout << (d2[n] < INF ? d2[n] : -1) << "\n";

    return 0;
}

